const money = (value) => Math.round((value + Number.EPSILON) * 100) / 100;

/**
 * Totals the credit codes generated by voucher purchases, one group per voucher shop item. Codes issued before
 * `sourceProductId` was recorded are grouped by the label they were issued under (the shop item's name at the time).
 */
export const summariseVoucherCodes = (codes, now = Date.now()) => {
  const groups = new Map();
  for (const code of codes) {
    if (!code.orderRef) continue;
    const key = code.sourceProductId ? `id:${code.sourceProductId}` : `label:${code.label || ''}`;
    const group = groups.get(key) || { productId: code.sourceProductId || '', label: code.label || '', issued: 0, active: 0, used: 0, expired: 0, unspent: 0 };
    const value = Number(code.discountValue) || 0;
    group.issued += 1;
    if (code.used) group.used += 1;
    else if (code.expiresAt && code.expiresAt <= now) group.expired += 1;
    else {
      group.active += 1;
      group.unspent = money(group.unspent + value);
    }
    groups.set(key, group);
  }
  return [...groups.values()];
};

/**
 * One row per voucher shop item, including items nobody has bought yet. Groups that match no current voucher product
 * (a renamed or removed item) keep their own row under the label they were issued with.
 */
export const voucherRows = (products, summaries) => {
  const voucherProducts = products.filter((product) => product.category === 'VOUCHERS');
  const claimed = new Set();
  const add = (row, summary) => {
    claimed.add(summary);
    for (const field of ['issued', 'active', 'used', 'expired']) row[field] += summary[field];
    row.unspent = money(row.unspent + summary.unspent);
  };
  const rows = voucherProducts.map((product) => {
    const row = { key: product.id, product, name: product.name, issued: 0, active: 0, used: 0, expired: 0, unspent: 0 };
    summaries.filter((summary) => summary.productId === product.id).forEach((summary) => add(row, summary));
    return row;
  });
  for (const summary of summaries) {
    if (claimed.has(summary) || summary.productId) continue;
    const row = rows.find((candidate) => candidate.product?.name === summary.label);
    if (row) add(row, summary);
  }
  for (const summary of summaries.filter((candidate) => !claimed.has(candidate))) {
    rows.push({ key: `${summary.productId}:${summary.label}`, product: null, name: summary.label || 'Voucher', issued: summary.issued, active: summary.active, used: summary.used, expired: summary.expired, unspent: summary.unspent });
  }
  return rows;
};
